<div class="tp-toolbar"><span class="tp-toolbar__spacer"></span><a class="tp-btn tp-btn--primary" href="/admin/posts/create"><?php echo icon('plus',16);?> <?php echo e(t('common.create'));?></a></div>
<div class="tp-card tp-card--table">
  <table class="tp-table"><thead><tr><th><?php echo e(t('common.title'));?></th><th>Slug</th><th><?php echo e(t('admin.published_at'));?></th><th>Tags</th><th><?php echo e(t('common.status'));?></th><th></th></tr></thead><tbody>
  <?php foreach($posts as $p){?><tr><td><?php echo e(\App\Core\I18n::pick($p['title']));?></td><td><code><?php echo e($p['slug']);?></code></td><td><?php echo e(date_fmt($p['published_at']));?></td><td><?php echo e($p['tags']);?></td><td><span class="tp-badge tp-badge--<?php echo(int)$p['is_published']?'success':'muted';?>"><?php echo(int)$p['is_published']?e(t('admin.published')):e(t('admin.draft'));?></span></td><td class="tp-row"><a class="tp-btn tp-btn--ghost tp-btn--sm" href="/admin/posts/<?php echo(int)$p['id'];?>"><?php echo icon('edit',14);?></a><a class="tp-btn tp-btn--ghost tp-btn--sm" href="<?php echo e(url('/blog/'.$p['slug']));?>" target="_blank"><?php echo icon('external',14);?></a><form method="post" action="/admin/posts/<?php echo(int)$p['id'];?>/delete" data-confirm="<?php echo e(t('common.confirm_delete'));?>"><?php echo csrf_field();?><button class="tp-btn tp-btn--danger tp-btn--sm" type="submit"><?php echo icon('trash',14);?></button></form></td></tr><?php }?>
  <?php if(!$posts){?><tr><td colspan="6" class="tp-center tp-text-3"><?php echo e(t('common.nothing'));?></td></tr><?php }?>
  </tbody></table>
</div>
